"""Write tools/letters/<slug>.json for wave 1. P1 and the quote are the first-edition Letter (already on the page);
P2 cites the register; P3 the three standards furthest from reach; P4 the vision."""
import json, sys
R = '/home/user/Perfect-Nations'
W = 'The work ahead is plain, and it is worth saying plainly. '
REACH = ' Each of them is within your reach.'
def VISION(name, dem, lead='Now imagine that same resolve turned toward every home in the country.'):
    return ('%s Picture Perfect %s: a morning when every family cooks with clean fuel and sits down to a full table; when every tap '
            'runs clean and every home has a safe toilet; when every child walks to a school where a teacher is waiting, and reads with '
            'ease by the age of ten; when every mother lives within reach of a clinic with the lights on, and every young person finds '
            'work that pays. And no %s falls below a decent life, because the nation has decided that none will.' % (lead, name, dem))
