INST = {'World Bank': 'World Bank', 'IMF': 'IMF', 'International Monetary Fund': 'IMF'}
def label(x):
    by = x['by'][0]
    for k, v in INST.items():
        if by.startswith(k): by = v
    import re
    m = re.findall(r'(20\d\d)', x['detail'])
    return '%s, %s' % (by, m[0]) if m else by

for slug in (sys.argv[1:] or N):
    code, dem, regs, p2, p3 = N[slug]
    d = json.load(open('%s/data/%s.json' % (R, slug)))
    p = json.load(open('%s/tools/nation/%s.json' % (R, slug)))
    name = d['nation']
    p1 = p['letter']['paras'][0]
    q = p['letter']['quote'].strip('“”"')
    srcs, seen = [], set()
    for want in regs:
        hits = [x for x in d['capital']['register'] if x['name'].startswith(want)]
        assert len(hits) >= 1, (slug, want)
        x = hits[0]
        if x['url'] not in seen:
            seen.add(x['url']); srcs.append([label(x), x['url']])
    g = sorted([x for x in d['guarantees'] if x['value'] is not None], key=lambda x: x['value'])[:3]
    for x in g:
        if x['url'] not in seen:
            seen.add(x['url']); srcs.append([x['source'], x['url']])
    lead = ('When peace comes, turn that same resolve toward every home in the country.' if slug == 'sudan' else
            'Now imagine that same resolve turned toward every home in the country.')
    p3full = W + p3 + (' None of it can wait for long, and all of it waits for peace.' if slug == 'sudan' else REACH)
    spec = {'nation': name, 'slug': slug, 'code': code, 'date': '2026-11-25',
            'excerpt': p1.split('. ')[0].rstrip('.') + '.', 'paras': [p1, p2, p3full, VISION(name, dem, lead)],
            'quote': q, 'sources': srcs}
    open('%s/tools/letters/%s.json' % (R, slug), 'w').write(json.dumps(spec, indent=2, ensure_ascii=False) + '\n')
    print(slug, len(srcs), 'sources')
